CREATE TEMP TABLE catalogue_input ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"id":"a3aff6a8-b2f8-5bea-82de-9a622ce97ec5","source_id":"0458","name_en":"floor fly (with barbell)","name_ar":"\u0627\u0644\u0630\u0628\u0627\u0628\u0629 \u0627\u0644\u0623\u0631\u0636\u064a\u0629 (\u0645\u0639 \u0627\u0644\u062d\u062f\u064a\u062f)","match_names":["floor fly (with barbell)"],"muscle":"chest","equipment":"barbell","aliases":["floor fly (with barbell)"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Lie flat on your back on the floor with your knees bent and feet flat on the ground.\nHold a barbell with an overhand grip, arms extended straight up over your chest.\nSlowly lower the barbell out to the sides, keeping a slight bend in your elbows.\nLower the barbell until your arms are parallel to the floor, feeling a stretch in your chest.\nPause for a moment, then squeeze your chest muscles to bring the barbell back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0630\u0631\u0627\u0639\u064a\u0646 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0641\u0648\u0642 \u0635\u062f\u0631\u0643.\n\u0623\u0646\u0632\u0644 \u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0646\u062d\u0646\u0627\u0621 \u0637\u0641\u064a\u0641 \u0641\u064a \u0645\u0631\u0641\u0642\u064a\u0643.\n\u0627\u062e\u0641\u0636 \u0627\u0644\u0628\u0627\u0631 \u062d\u062a\u0649 \u062a\u0635\u0628\u062d \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u062a\u0648\u0627\u0632\u064a\u062a\u064a\u0646 \u0645\u0639 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0633\u062a\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0635\u062f\u0631\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0639\u0636\u0644\u0627\u062a \u0635\u062f\u0631\u0643 \u0644\u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u062d\u062f\u064a\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0458","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["deltoids","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0458-neonEDL.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0458-neonEDL.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"558c1090-45b0-5deb-843f-8a37516c02ed","source_id":"0459","name_en":"flutter kicks","name_ar":"\u0631\u0643\u0644\u0627\u062a \u0631\u0641\u0631\u0641\u0629","match_names":["flutter kicks"],"muscle":"glutes","equipment":"bodyweight","aliases":["flutter kicks"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Lie flat on your back with your legs extended and your hands by your sides.\nEngage your core and lift your legs off the ground about 6 inches.\nKeeping your legs straight, alternate lifting one leg slightly higher than the other.\nContinue this fluttering motion for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u064a\u0643 \u0648\u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u0631\u0641\u0639 \u0633\u0627\u0642\u064a\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636 \u062d\u0648\u0627\u0644\u064a 6 \u0628\u0648\u0635\u0627\u062a.\n\u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0633\u0627\u0642\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646\u060c \u0642\u0645 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u0631\u0641\u0639 \u0633\u0627\u0642 \u0648\u0627\u062d\u062f\u0629 \u0623\u0639\u0644\u0649 \u0642\u0644\u064a\u0644\u0627\u064b \u0645\u0646 \u0627\u0644\u0623\u062e\u0631\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062d\u0631\u0643\u0629 \u0627\u0644\u0631\u0641\u0631\u0641\u0629 \u0647\u0630\u0647 \u0644\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0459","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hip flexors","lower abs"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0459-UVo2Qs2.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0459-UVo2Qs2.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"3c3f805e-da5b-51e7-8fc1-e19ef1318bb6","source_id":"1472","name_en":"forward jump","name_ar":"\u0627\u0644\u0642\u0641\u0632 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645","match_names":["forward jump"],"muscle":"quads","equipment":"bodyweight","aliases":["forward jump"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart.\nBend your knees and lower your body into a squat position.\nSwing your arms back for momentum.\nJump forward explosively, extending your hips, knees, and ankles.\nLand softly on the balls of your feet and immediately go into the next jump.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621.\n\u0623\u0631\u062c\u062d\u0629 \u0630\u0631\u0627\u0639\u064a\u0643 \u0644\u0644\u062e\u0644\u0641 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0632\u062e\u0645.\n\u0627\u0642\u0641\u0632 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 \u0628\u0634\u0643\u0644 \u0645\u062a\u0641\u062c\u0631\u060c \u0648\u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646 \u0648\u0627\u0644\u0643\u0627\u062d\u0644\u064a\u0646.\n\u0627\u0647\u0628\u0637 \u0628\u0647\u062f\u0648\u0621 \u0639\u0644\u0649 \u0645\u0634\u0637 \u0642\u062f\u0645\u064a\u0643 \u062b\u0645 \u0627\u0646\u062a\u0642\u0644 \u0641\u0648\u0631\u064b\u0627 \u0625\u0644\u0649 \u0627\u0644\u0642\u0641\u0632\u0629 \u0627\u0644\u062a\u0627\u0644\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1472","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"quads","secondary_muscles":["calves","hamstrings","glutes"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1472-uZKq7lo.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1472-uZKq7lo.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"ab09776d-1fbe-5ef4-8446-4f88d22a101b","source_id":"3470","name_en":"forward lunge (male)","name_ar":"\u0627\u0646\u062f\u0641\u0627\u0639 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 (\u0630\u0643\u0631)","match_names":["forward lunge (male)"],"muscle":"glutes","equipment":"bodyweight","aliases":["forward lunge (male)"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet hip-width apart and hands on your hips.\nTake a big step forward with your right foot, lowering your body into a lunge position.\nBend your right knee to about 90 degrees, keeping your knee aligned with your ankle.\nPush off with your right foot and return to the starting position.\nRepeat with your left leg, alternating sides for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0648\u0631\u0643\u064a\u0643.\n\u0627\u062a\u062e\u0630 \u062e\u0637\u0648\u0629 \u0643\u0628\u064a\u0631\u0629 \u0644\u0644\u0623\u0645\u0627\u0645 \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649\u060c \u0648\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u062f\u0641\u0627\u0639.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0628\u0632\u0627\u0648\u064a\u0629 90 \u062f\u0631\u062c\u0629 \u062a\u0642\u0631\u064a\u0628\u064b\u0627\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0645\u062d\u0627\u0630\u0627\u0629 \u0631\u0643\u0628\u062a\u0643 \u0645\u0639 \u0643\u0627\u062d\u0644\u0643.\n\u0627\u062f\u0641\u0639 \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u062b\u0645 \u0639\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0645\u0639 \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0633\u0631\u0649\u060c \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0644\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3470","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3470-kMzUs9Y.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3470-kMzUs9Y.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"36f1c9f7-0795-5eaa-8a9a-158eef22f2bc","source_id":"3194","name_en":"frankenstein squat","name_ar":"\u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0641\u0631\u0627\u0646\u0643\u0634\u062a\u0627\u064a\u0646","match_names":["frankenstein squat"],"muscle":"glutes","equipment":"barbell","aliases":["frankenstein squat"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet shoulder-width apart and hold the barbell in front of your body with straight arms.\nKeeping your back straight, lower your body by bending at the knees and hips, as if sitting back into a chair.\nContinue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.\nPause for a moment, then push through your heels to return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u062f\u064a\u062f \u0623\u0645\u0627\u0645 \u062c\u0633\u0645\u0643 \u0628\u0623\u0630\u0631\u0639 \u0645\u0633\u062a\u0642\u064a\u0645\u0629.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643\u060c \u0648\u0642\u0645 \u0628\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646 \u0648\u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0643\u0645\u0627 \u0644\u0648 \u0643\u0646\u062a \u062a\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0633\u064a.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0627\u0646\u062e\u0641\u0627\u0636 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0641\u062e\u0630\u0627\u0643 \u0645\u0648\u0627\u0632\u064a\u064a\u0646 \u0644\u0644\u0623\u0631\u0636\u060c \u0623\u0648 \u0625\u0644\u0649 \u0623\u062f\u0646\u0649 \u0645\u0633\u062a\u0648\u0649 \u064a\u0645\u0643\u0646\u0643 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064a\u0647 \u0628\u0634\u0643\u0644 \u0645\u0631\u064a\u062d.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0643\u0639\u0628\u064a\u0643 \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3194","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3194-bdWcbaU.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3194-bdWcbaU.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"8c29b00f-372c-5a5d-8941-876e4dca960b","source_id":"2429","name_en":"frog crunch","name_ar":"\u0623\u0632\u0645\u0629 \u0627\u0644\u0636\u0641\u062f\u0639","match_names":["frog crunch"],"muscle":"core","equipment":"bodyweight","aliases":["frog crunch"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Lie flat on your back with your knees bent and feet flat on the ground.\nPlace your hands behind your head with your elbows pointing outwards.\nEngaging your abs, lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.\nPause for a moment at the top, then slowly lower your upper body back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643 \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0645\u0631\u0641\u0642\u064a\u0643 \u0644\u0644\u062e\u0627\u0631\u062c.\n\u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0639\u0636\u0644\u0627\u062a \u0628\u0637\u0646\u0643\u060c \u0627\u0631\u0641\u0639 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u062b\u0645 \u0627\u0646\u062d\u0646\u064a \u0644\u0644\u0623\u0645\u0627\u0645 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u062c\u0630\u0639\u0643 \u0628\u0632\u0627\u0648\u064a\u0629 45 \u062f\u0631\u062c\u0629.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2429","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2429-FFRP97T.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2429-FFRP97T.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"6345547a-9bec-5073-8708-eac9d7ee538d","source_id":"3301","name_en":"frog planche","name_ar":"\u0628\u0644\u0627\u0646\u0634 \u0627\u0644\u0636\u0641\u062f\u0639","match_names":["frog planche"],"muscle":"core","equipment":"bodyweight","aliases":["frog planche"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start in a push-up position with your hands shoulder-width apart and your feet together.\nBend your elbows and lower your body towards the ground, keeping your back straight.\nAs you lower your body, lift your feet off the ground and bring your knees towards your chest.\nHold this position for a few seconds, then extend your legs back out and push yourself back up to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0641\u064a \u0648\u0636\u0639 \u0627\u0644\u0636\u063a\u0637 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u064a\u062f\u064a\u0643 \u0628\u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0639\u064b\u0627.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0648\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643.\n\u0623\u062b\u0646\u0627\u0621 \u062e\u0641\u0636 \u062c\u0633\u0645\u0643\u060c \u0627\u0631\u0641\u0639\u064a \u0642\u062f\u0645\u064a\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636 \u0648\u0627\u062c\u0644\u0628\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0648\u0636\u0639 \u0644\u0628\u0636\u0639 \u062b\u0648\u0627\u0646\u060c \u062b\u0645 \u0642\u0645 \u0628\u0645\u062f \u0633\u0627\u0642\u064a\u0643 \u0644\u0644\u062e\u0644\u0641 \u0648\u0627\u062f\u0641\u0639 \u0646\u0641\u0633\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3301","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["shoulders","chest","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3301-rQhGcin.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3301-rQhGcin.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"fa7b632f-6bdc-55fe-85d8-f321f3f36782","source_id":"3296","name_en":"front lever","name_ar":"\u0631\u0627\u0641\u0639\u0629 \u0623\u0645\u0627\u0645\u064a\u0629","match_names":["front lever"],"muscle":"core","equipment":"bodyweight","aliases":["front lever"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start by hanging from a pull-up bar with an overhand grip, hands shoulder-width apart.\nEngage your core and pull your shoulder blades down and back.\nBend your knees and tuck them towards your chest.\nSimultaneously, lift your legs up and extend them straight out in front of you, keeping your body parallel to the ground.\nHold this position for as long as you can, aiming for a full front lever position.\nTo release, slowly lower your legs back down and return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u062a\u0639\u0644\u064a\u0642 \u0645\u0646 \u0634\u0631\u064a\u0637 \u0627\u0644\u0633\u062d\u0628 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0627\u0644\u064a\u062f\u064a\u0646 \u0628\u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u0633\u062d\u0628 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0625\u0644\u0649 \u0627\u0644\u0623\u0633\u0641\u0644 \u0648\u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0627\u062f\u0641\u0639\u0647\u0645\u0627 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643.\n\u0641\u064a \u0627\u0644\u0648\u0642\u062a \u0646\u0641\u0633\u0647\u060c \u0627\u0631\u0641\u0639\u064a \u0633\u0627\u0642\u064a\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0648\u0645\u062f\u064a\u0647\u0645\u0627 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0623\u0645\u0627\u0645\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u062c\u0633\u0645\u0643 \u0645\u0648\u0627\u0632\u064a\u064b\u0627 \u0644\u0644\u0623\u0631\u0636.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0648\u0636\u0639 \u0644\u0623\u0637\u0648\u0644 \u0641\u062a\u0631\u0629 \u0645\u0645\u0643\u0646\u0629\u060c \u0645\u0633\u062a\u0647\u062f\u0641\u064b\u0627 \u0627\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0631\u0627\u0641\u0639\u0629 \u0627\u0644\u0623\u0645\u0627\u0645\u064a\u0629 \u0627\u0644\u0643\u0627\u0645\u0644\u0629.\n\u0644\u0644\u0625\u0641\u0631\u0627\u062c\u060c \u0642\u0645 \u0628\u062e\u0641\u0636 \u0633\u0627\u0642\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0627\u0644\u0623\u0633\u0641\u0644 \u062b\u0645 \u0639\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3296","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["lats","shoulders","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3296-PkCN2lv.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3296-PkCN2lv.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"efe6392e-3267-58fe-88f7-25ff5109bb4d","source_id":"3295","name_en":"front lever reps","name_ar":"\u0645\u0645\u062b\u0644\u0648 \u0627\u0644\u0631\u0627\u0641\u0639\u0629 \u0627\u0644\u0623\u0645\u0627\u0645\u064a\u0629","match_names":["front lever reps"],"muscle":"back","equipment":"bodyweight","aliases":["front lever reps"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Hang from a pull-up bar with an overhand grip, palms facing away from you.\nEngage your core and pull your shoulder blades down and back.\nKeeping your body straight, lift your legs up until they are parallel to the ground.\nHold this position for as long as you can, aiming for 10-20 seconds.\nSlowly lower your legs back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u0627\u0644\u062a\u0639\u0644\u064a\u0642 \u0645\u0646 \u0634\u0631\u064a\u0637 \u0627\u0644\u0633\u062d\u0628 \u0628\u0642\u0628\u0636\u0629 \u064a\u062f\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646\u0643.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u0633\u062d\u0628 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0625\u0644\u0649 \u0627\u0644\u0623\u0633\u0641\u0644 \u0648\u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u062c\u0633\u0645\u0643\u060c \u0627\u0631\u0641\u0639 \u0633\u0627\u0642\u064a\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u062d\u062a\u0649 \u062a\u0635\u0628\u062d \u0645\u0648\u0627\u0632\u064a\u0629 \u0644\u0644\u0623\u0631\u0636.\n\u062d\u0627\u0641\u0638\u064a \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0648\u0636\u0639 \u0644\u0623\u0637\u0648\u0644 \u0641\u062a\u0631\u0629 \u0645\u0645\u0643\u0646\u0629\u060c \u0644\u0645\u062f\u0629 10-20 \u062b\u0627\u0646\u064a\u0629.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u0633\u0627\u0642\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3295","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"upper back","secondary_muscles":["core","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3295-hbY9wqG.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3295-hbY9wqG.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"7a9da08c-83a4-5f1b-8fdc-bc0daca4688f","source_id":"0464","name_en":"front plank with twist","name_ar":"\u0627\u0644\u0644\u0648\u062d \u0627\u0644\u0623\u0645\u0627\u0645\u064a \u0645\u0639 \u062a\u0637\u0648\u0631","match_names":["front plank with twist"],"muscle":"core","equipment":"bodyweight","aliases":["front plank with twist"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.\nEngage your core and glutes to maintain a stable position.\nRotate your torso to the right, lifting your right arm and extending it towards the ceiling.\nKeep your hips and legs stable as you twist.\nHold for a moment, then return to the starting position.\nRepeat the twist on the left side.\nContinue alternating sides for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0644\u0648\u062d \u0627\u0644\u062e\u0634\u0628\u064a \u0627\u0644\u0645\u0631\u062a\u0641\u0639 \u0645\u0639 \u0648\u0636\u0639 \u064a\u062f\u064a\u0643 \u0645\u0628\u0627\u0634\u0631\u0629 \u062a\u062d\u062a \u0643\u062a\u0641\u064a\u0643 \u0648\u062c\u0633\u0645\u0643 \u0641\u064a \u062e\u0637 \u0645\u0633\u062a\u0642\u064a\u0645 \u0645\u0646 \u0627\u0644\u0631\u0623\u0633 \u0625\u0644\u0649 \u0623\u062e\u0645\u0635 \u0627\u0644\u0642\u062f\u0645\u064a\u0646.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629 \u0644\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0648\u0636\u0639 \u0645\u0633\u062a\u0642\u0631.\n\u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u062c\u0630\u0639\u0643 \u0625\u0644\u0649 \u0627\u0644\u064a\u0645\u064a\u0646\u060c \u0648\u0627\u0631\u0641\u0639 \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0648\u0645\u062f\u0647\u0627 \u0646\u062d\u0648 \u0627\u0644\u0633\u0642\u0641.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u062b\u0628\u0627\u062a \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0633\u0627\u0642\u064a\u0646 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0627\u0644\u062a\u0648\u0627\u0621.\n\u0627\u0646\u062a\u0638\u0631 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0639\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u062a\u0637\u0648\u0631 \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0623\u064a\u0633\u0631.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0464","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["obliques","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0464-CosupLu.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0464-CosupLu.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"db4dd976-c0eb-57bc-8be8-0813c0a9efeb","source_id":"3315","name_en":"full maltese","name_ar":"\u0645\u0627\u0644\u0637\u064a \u0643\u0627\u0645\u0644","match_names":["full maltese"],"muscle":"core","equipment":"bodyweight","aliases":["full maltese"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start by standing with your feet shoulder-width apart and your arms extended straight out to the sides.\nSlowly lean forward, keeping your arms straight, until your upper body is parallel to the ground.\nEngage your core and hold this position for a few seconds.\nReturn to the starting position by pushing through your feet and standing back up.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u0648\u0642\u0648\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646.\n\u0627\u0646\u062d\u0646\u064a \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646\u060c \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0645\u0648\u0627\u0632\u064a\u064b\u0627 \u0644\u0644\u0623\u0631\u0636.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u062d\u062a\u0641\u0638 \u0628\u0647\u0630\u0627 \u0627\u0644\u0648\u0636\u0639 \u0644\u0628\u0636\u0639 \u062b\u0648\u0627\u0646.\n\u0627\u0631\u062c\u0639 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0645\u0646 \u062e\u0644\u0627\u0644 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0642\u062f\u0645\u064a\u0643 \u0648\u0627\u0644\u0648\u0642\u0648\u0641 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3315","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["shoulders","chest"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3315-YRaCa5Y.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3315-YRaCa5Y.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"94a65883-e9b5-5f06-8bef-f0eaaaabb0ee","source_id":"3299","name_en":"full planche","name_ar":"\u0628\u0644\u0627\u0646\u0634 \u0643\u0627\u0645\u0644","match_names":["full planche"],"muscle":"core","equipment":"bodyweight","aliases":["full planche"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start in a push-up position with your hands shoulder-width apart and your fingers pointing forward.\nEngage your core and slowly shift your weight forward, lifting your feet off the ground.\nContinue shifting your weight forward until your body is parallel to the ground, balancing on your hands.\nHold this position for as long as you can, maintaining a straight body line.\nSlowly lower your feet back to the ground and return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0636\u063a\u0637 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u064a\u062f\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u062a\u0648\u062c\u064a\u0647 \u0623\u0635\u0627\u0628\u0639\u0643 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u062d\u0631\u0643 \u0648\u0632\u0646\u0643 \u0628\u0628\u0637\u0621 \u0644\u0644\u0623\u0645\u0627\u0645\u060c \u0648\u0627\u0631\u0641\u0639 \u0642\u062f\u0645\u064a\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0646\u0642\u0644 \u0648\u0632\u0646\u0643 \u0644\u0644\u0623\u0645\u0627\u0645 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u062c\u0633\u0645\u0643 \u0645\u0648\u0627\u0632\u064a\u064b\u0627 \u0644\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0627\u0644\u062a\u0648\u0627\u0632\u0646 \u0639\u0644\u0649 \u064a\u062f\u064a\u0643.\n\u062d\u0627\u0641\u0638\u064a \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0648\u0636\u0639 \u0644\u0623\u0637\u0648\u0644 \u0641\u062a\u0631\u0629 \u0645\u0645\u0643\u0646\u0629\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u062e\u0637 \u0645\u0633\u062a\u0642\u064a\u0645 \u0644\u0644\u062c\u0633\u0645.\n\u0623\u0646\u0632\u0644 \u0642\u062f\u0645\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u062b\u0645 \u0639\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3299","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["shoulders","chest","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3299-YZ4961r.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3299-YZ4961r.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"d25d7e1b-5c3d-53d3-8c25-bfc73c27ce53","source_id":"3327","name_en":"full planche push-up","name_ar":"\u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u0643\u0627\u0645\u0644 \u0644\u0644\u0628\u0644\u0627\u0646\u0634","match_names":["full planche push-up"],"muscle":"chest","equipment":"bodyweight","aliases":["full planche push-up"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start in a push-up position with your hands placed slightly wider than shoulder-width apart.\nEngage your core and lower your body down towards the ground, keeping your elbows close to your sides.\nAs you lower yourself, lean your body forward and lift your feet off the ground, balancing on your hands.\nContinue to lower your body until your chest is just above the ground.\nPush through your hands and extend your arms to lift your body back up to the starting position.\nMaintain a straight line from your head to your heels throughout the movement.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0636\u063a\u0637 \u0645\u0639 \u0648\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0645\u0633\u0627\u0641\u0629 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u0627\u064b \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u0639\u0646\u062f\u0645\u0627 \u062a\u0646\u0632\u0644 \u0646\u0641\u0633\u0643\u060c \u0642\u0645 \u0628\u0625\u0645\u0627\u0644\u0629 \u062c\u0633\u0645\u0643 \u0644\u0644\u0623\u0645\u0627\u0645 \u0648\u0627\u0631\u0641\u0639 \u0642\u062f\u0645\u064a\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0627\u0644\u062a\u0648\u0627\u0632\u0646 \u0639\u0644\u0649 \u064a\u062f\u064a\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0635\u062f\u0631\u0643 \u0641\u0648\u0642 \u0627\u0644\u0623\u0631\u0636 \u0645\u0628\u0627\u0634\u0631\u0629\u064b.\n\u0627\u062f\u0641\u0639 \u0628\u064a\u062f\u064a\u0643 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0644\u0631\u0641\u0639 \u062c\u0633\u0645\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u062e\u0637 \u0645\u0633\u062a\u0642\u064a\u0645 \u0645\u0646 \u0631\u0623\u0633\u0643 \u0625\u0644\u0649 \u0643\u0639\u0628\u0643 \u0637\u0648\u0627\u0644 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3327","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["shoulders","triceps","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3327-gw9PqGk.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3327-gw9PqGk.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"16f454d5-0270-5cd5-8e33-093089ebb368","source_id":"0466","name_en":"gironda sternum chin","name_ar":"\u062c\u064a\u0631\u0648\u0646\u062f\u0627 \u0627\u0644\u0642\u0635 \u0627\u0644\u0630\u0642\u0646","match_names":["gironda sternum chin"],"muscle":"back","equipment":"bodyweight","aliases":["gironda sternum chin"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand facing a high bar with your feet shoulder-width apart.\nReach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.\nHang from the bar with your arms fully extended and your body straight.\nEngage your lats and biceps to pull your chest up towards the bar, leading with your sternum.\nPause for a moment at the top, then slowly lower yourself back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0634\u0631\u064a\u0637 \u0645\u0631\u062a\u0641\u0639 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0623\u0639\u0644\u0649 \u0648\u0623\u0645\u0633\u0643 \u0628\u0627\u0644\u0628\u0627\u0631 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0623\u0639\u0631\u0636 \u0642\u0644\u064a\u0644\u0627\u064b \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0634\u0646\u0642 \u0645\u0646 \u0627\u0644\u0634\u0631\u064a\u0637 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u062c\u0633\u0645\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0628\u0637\u0646 \u0648\u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646 \u0644\u0633\u062d\u0628 \u0635\u062f\u0631\u0643 \u0646\u062d\u0648 \u0627\u0644\u0634\u0631\u064a\u0637\u060c \u0645\u0645\u0627 \u064a\u0624\u062f\u064a \u0625\u0644\u0649 \u0639\u0638\u0645\u0629 \u0627\u0644\u0642\u0635.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0646\u0641\u0633\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0466","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["biceps","rhomboids","rear deltoids"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0466-IL0JUxR.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0466-IL0JUxR.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"6c2d0dce-f7b5-5f90-8989-cf94dfbfd2ed","source_id":"3561","name_en":"glute bridge march","name_ar":"\u0645\u0633\u064a\u0631\u0629 \u062c\u0633\u0631 \u063a\u0644\u0648\u062a","match_names":["glute bridge march"],"muscle":"glutes","equipment":"bodyweight","aliases":["glute bridge march"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Lie flat on your back with your knees bent and feet flat on the ground.\nEngage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.\nWhile keeping your hips lifted, lift one foot off the ground and bring your knee towards your chest.\nLower your foot back to the ground and repeat the movement with the other leg.\nContinue alternating legs in a marching motion while maintaining the bridge position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629 \u0648\u0627\u0631\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0644\u062a\u0634\u0643\u0644 \u062e\u0637\u064b\u0627 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627 \u0645\u0646 \u0631\u0643\u0628\u062a\u064a\u0643 \u0625\u0644\u0649 \u0643\u062a\u0641\u064a\u0643.\n\u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0631\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0627\u0631\u0641\u0639 \u0642\u062f\u0645\u064b\u0627 \u0648\u0627\u062d\u062f\u0629 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636 \u0648\u0627\u062c\u0644\u0628 \u0631\u0643\u0628\u062a\u0643 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643.\n\u0623\u0646\u0632\u0644 \u0642\u062f\u0645\u0643 \u0625\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0643\u0631\u0631 \u0627\u0644\u062d\u0631\u0643\u0629 \u0645\u0639 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0623\u062e\u0631\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0623\u0631\u062c\u0644 \u0641\u064a \u062d\u0631\u0643\u0629 \u0627\u0644\u0633\u064a\u0631 \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u062c\u0633\u0631.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3561","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","quadriceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3561-GibBPPg.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3561-GibBPPg.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"9ea79c3d-9ce8-5409-8998-130a504aea14","source_id":"3523","name_en":"glute bridge two legs on bench (male)","name_ar":"\u062c\u0633\u0631 \u0627\u0644\u0623\u0644\u0648\u064a\u0629 \u0642\u062f\u0645\u064a\u0646 \u0639\u0644\u0649 \u0645\u0642\u0627\u0639\u062f \u0627\u0644\u0628\u062f\u0644\u0627\u0621 (\u0630\u0643\u0631)","match_names":["glute bridge two legs on bench (male)"],"muscle":"glutes","equipment":"bodyweight","aliases":["glute bridge two legs on bench (male)"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Sit on the edge of a bench with your back against it and your feet flat on the ground.\nPlace your hands on the bench beside your hips for support.\nEngage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.\nPause for a moment at the top, then slowly lower your hips back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u062d\u0627\u0641\u0629 \u0627\u0644\u0645\u0642\u0639\u062f \u0648\u0627\u0633\u0646\u062f \u0638\u0647\u0631\u0643 \u0625\u0644\u064a\u0647 \u0648\u0642\u062f\u0645\u0627\u0643 \u0645\u0633\u0637\u062d\u062a\u0627\u0646 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0628\u062c\u0627\u0646\u0628 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u062f\u0639\u0645.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629 \u0648\u0623\u0648\u062a\u0627\u0631 \u0627\u0644\u0631\u0643\u0628\u0629\u060c \u062b\u0645 \u0627\u0631\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0639\u0646 \u0627\u0644\u0645\u0642\u0639\u062f \u062d\u062a\u0649 \u064a\u0634\u0643\u0644 \u062c\u0633\u0645\u0643 \u062e\u0637\u064b\u0627 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627 \u0645\u0646 \u0631\u0643\u0628\u062a\u064a\u0643 \u0625\u0644\u0649 \u0643\u062a\u0641\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0648\u0631\u0643\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3523","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3523-aWedzZX.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3523-aWedzZX.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"5d81e7f1-97a3-5f51-897e-8e35f0977988","source_id":"3193","name_en":"glute-ham raise","name_ar":"\u0631\u0641\u0639 \u0644\u062d\u0645 \u0627\u0644\u062e\u0646\u0632\u064a\u0631","match_names":["glute-ham raise"],"muscle":"hamstrings","equipment":"bodyweight","aliases":["glute-ham raise"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Adjust the glute-ham raise machine to fit your body.\nPosition yourself face down on the machine with your ankles secured.\nPlace your hands on your chest or cross them over your chest.\nEngage your hamstrings and glutes to lift your upper body up towards the ceiling.\nContinue lifting until your body is in a straight line from your head to your heels.\nPause for a moment at the top, then slowly lower your body back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0622\u0644\u0629 \u0631\u0641\u0639 \u063a\u0644\u0648\u062a \u0644\u062d\u0645 \u0627\u0644\u062e\u0646\u0632\u064a\u0631 \u0644\u062a\u0646\u0627\u0633\u0628 \u062c\u0633\u0645\u0643.\n\u0636\u0639 \u0646\u0641\u0633\u0643 \u0648\u0648\u062c\u0647\u0643 \u0644\u0623\u0633\u0641\u0644 \u0639\u0644\u0649 \u0627\u0644\u062c\u0647\u0627\u0632 \u0645\u0639 \u062a\u0623\u0645\u064a\u0646 \u0643\u0627\u062d\u0644\u064a\u0643.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0635\u062f\u0631\u0643 \u0623\u0648 \u0627\u0639\u0628\u0631\u0647\u0645\u0627 \u0641\u0648\u0642 \u0635\u062f\u0631\u0643.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0623\u0648\u062a\u0627\u0631 \u0627\u0644\u0631\u0643\u0628\u0629 \u0648\u0627\u0644\u0623\u0631\u062f\u0627\u0641 \u0644\u0631\u0641\u0639 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0646\u062d\u0648 \u0627\u0644\u0633\u0642\u0641.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0631\u0641\u0639 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u062c\u0633\u0645\u0643 \u0641\u064a \u062e\u0637 \u0645\u0633\u062a\u0642\u064a\u0645 \u0645\u0646 \u0631\u0623\u0633\u0643 \u0625\u0644\u0649 \u0643\u0639\u0628\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3193","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"hamstrings","secondary_muscles":["glutes","lower back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3193-Vvwjz6N.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3193-Vvwjz6N.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"ebb62fb1-121c-5bef-8398-d02ba95061ae","source_id":"0467","name_en":"gorilla chin","name_ar":"\u0630\u0642\u0646 \u0627\u0644\u063a\u0648\u0631\u064a\u0644\u0627","match_names":["gorilla chin"],"muscle":"core","equipment":"bodyweight","aliases":["gorilla chin"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart and your knees slightly bent.\nGrasp a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.\nHang from the bar with your arms fully extended and your palms facing away from you.\nEngage your core and pull your body up towards the bar, bringing your chin above the bar.\nPause for a moment at the top, then slowly lower your body back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0623\u0645\u0633\u0643 \u0634\u0631\u064a\u0637 \u0627\u0644\u0633\u062d\u0628 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0628\u064a\u0646\u0643\u0645\u0627 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u0627\u0644\u062a\u0639\u0644\u064a\u0642 \u0645\u0646 \u0627\u0644\u0634\u0631\u064a\u0637 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646\u0643.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u0633\u062d\u0628 \u062c\u0633\u0645\u0643 \u0644\u0623\u0639\u0644\u0649 \u0646\u062d\u0648 \u0627\u0644\u0634\u0631\u064a\u0637\u060c \u0645\u0645\u0627 \u064a\u062c\u0639\u0644 \u0630\u0642\u0646\u0643 \u0641\u0648\u0642 \u0627\u0644\u0634\u0631\u064a\u0637.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0467","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["forearms","biceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0467-bmwlYvD.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0467-bmwlYvD.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"cf590a8f-9abc-5d58-8870-d63b518b5e3a","source_id":"0469","name_en":"groin crunch","name_ar":"\u0623\u0632\u0645\u0629 \u0627\u0644\u0641\u062e\u0630","match_names":["groin crunch"],"muscle":"core","equipment":"bodyweight","aliases":["groin crunch"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Lie flat on your back with your knees bent and feet flat on the ground.\nPlace your hands behind your head with your elbows pointing outwards.\nEngaging your abs, lift your legs off the ground, bringing your knees towards your chest.\nPause for a moment at the top, then slowly lower your legs back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0636\u0639 \u064a\u062f\u064a\