eyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1384-AxFoqAD.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1384-AxFoqAD.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"476af9e3-adf8-574e-80a1-efdadcec9ed1","source_id":"3221","name_en":"half knee bends (male)","name_ar":"\u062b\u0646\u064a \u0646\u0635\u0641 \u0627\u0644\u0631\u0643\u0628\u0629 (\u0630\u0643\u0631)","match_names":["half knee bends (male)"],"muscle":"cardio","equipment":"bodyweight","aliases":["half knee bends (male)"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart.\nBend your knees and lower your body down as if you were sitting back into a chair.\nKeep your chest up and your weight in your heels.\nPause for a moment at the bottom, then push through your heels to return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0644\u0644\u0623\u0633\u0641\u0644 \u0643\u0645\u0627 \u0644\u0648 \u0643\u0646\u062a \u062a\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u0643\u0631\u0633\u064a.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0635\u062f\u0631\u0643 \u0645\u0631\u062a\u0641\u0639\u064b\u0627 \u0648\u0648\u0632\u0646\u0643 \u0641\u064a \u0643\u0639\u0628\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0643\u0639\u0628\u064a\u0643 \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3221","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"cardio","classification_status":"needs_review","source_target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","glutes"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3221-ia6kIIl.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3221-ia6kIIl.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"5dabccaa-94dc-5975-860b-6379d4242c9b","source_id":"3202","name_en":"half sit-up (male)","name_ar":"\u0646\u0635\u0641 \u0627\u0644\u062c\u0644\u0648\u0633 (\u0630\u0643\u0631)","match_names":["half sit-up (male)"],"muscle":"core","equipment":"bodyweight","aliases":["half sit-up (male)"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Lie flat on your back with your knees bent and feet flat on the ground.\nPlace your hands behind your head with your elbows pointing outwards.\nEngaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.\nPause for a moment at the top, then slowly lower your upper body back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643 \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0645\u0631\u0641\u0642\u064a\u0643 \u0644\u0644\u062e\u0627\u0631\u062c.\n\u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0639\u0636\u0644\u0627\u062a \u0628\u0637\u0646\u0643\u060c \u0627\u0631\u0641\u0639 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u062b\u0645 \u0627\u0646\u062d\u0646\u064a \u0644\u0644\u0623\u0645\u0627\u0645 \u062d\u062a\u0649 \u064a\u0635\u0644 \u062c\u0630\u0639\u0643 \u0625\u0644\u0649 \u0632\u0627\u0648\u064a\u0629 45 \u062f\u0631\u062c\u0629.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3202","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3202-iQ241UP.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3202-iQ241UP.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"344ac760-84f1-5089-8efd-6efa4b7d167b","source_id":"1511","name_en":"hamstring stretch","name_ar":"\u062a\u0645\u062a\u062f \u0627\u0648\u062a\u0627\u0631 \u0627\u0644\u0631\u0643\u0628\u0629","match_names":["hamstring stretch"],"muscle":"hamstrings","equipment":"bodyweight","aliases":["hamstring stretch"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart.\nStep forward with your right foot and shift your weight onto your right leg.\nKeeping your back straight, slowly bend forward at the hips, reaching towards your right foot with both hands.\nHold the stretch for 20-30 seconds, then return to the starting position.\nRepeat on the other side.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u062a\u0642\u062f\u0645 \u0644\u0644\u0623\u0645\u0627\u0645 \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0648\u062d\u0631\u0643 \u0648\u0632\u0646\u0643 \u0639\u0644\u0649 \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0645\u0646\u0649.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643\u060c \u062b\u0645 \u0627\u0646\u062d\u0646\u064a \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0648\u0648\u0635\u0644 \u0625\u0644\u0649 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0645\u062f\u0629 20-30 \u062b\u0627\u0646\u064a\u0629\u060c \u062b\u0645 \u0639\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1511","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"hamstrings","secondary_muscles":["glutes"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1511-99rWm7w.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1511-99rWm7w.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"ffb1f0fc-8aa6-5d5f-8b13-dc802d30617e","source_id":"2139","name_en":"hands bike","name_ar":"\u062f\u0631\u0627\u062c\u0629 \u0627\u0644\u0623\u064a\u062f\u064a","match_names":["hands bike"],"muscle":"chest","equipment":"upper_body_ergometer","aliases":["hands bike"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the seat height and handlebar position to a comfortable level.\nSit on the ergometer with your back straight and feet on the pedals.\nGrasp the handles with your hands and position your arms at a 90-degree angle.\nStart pedaling with your hands, pushing and pulling the handles in a controlled motion.\nContinue pedaling for the desired duration or number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0645\u0642\u0639\u062f \u0648\u0645\u0648\u0636\u0639 \u0627\u0644\u0645\u0642\u0648\u062f \u0625\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0645\u0631\u064a\u062d.\n\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u064a\u0627\u0633 \u0627\u0644\u0639\u0645\u0644 \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u0627\u064b \u0648\u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u062f\u0648\u0627\u0633\u0627\u062a.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u064a\u062f\u064a\u0643 \u0648\u0636\u0639 \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0632\u0627\u0648\u064a\u0629 90 \u062f\u0631\u062c\u0629.\n\u0627\u0628\u062f\u0623 \u0641\u064a \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u062f\u0648\u0627\u0633\u0627\u062a \u0628\u064a\u062f\u064a\u0643\u060c \u0648\u0627\u062f\u0641\u0639 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0648\u0627\u0633\u062d\u0628\u0647\u0627 \u0628\u062d\u0631\u0643\u0629 \u0645\u062a\u062d\u0643\u0645 \u0641\u064a\u0647\u0627.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u062f\u0648\u0627\u0633\u0627\u062a \u0644\u0644\u0645\u062f\u0629 \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629 \u0623\u0648 \u0639\u062f\u062f \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2139","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["triceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2139-pAIWRGu.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2139-pAIWRGu.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"6b032689-450c-59fc-8db2-596dba24f751","source_id":"3218","name_en":"hands clasped circular toe touch (male)","name_ar":"\u0627\u0644\u0623\u064a\u062f\u064a \u0627\u0644\u0645\u0634\u062f\u0648\u062f\u0629 \u0628\u0625\u0635\u0628\u0639 \u062f\u0627\u0626\u0631\u064a \u062a\u0639\u0645\u0644 \u0628\u0627\u0644\u0644\u0645\u0633 (\u0630\u0643\u0631)","match_names":["hands clasped circular toe touch (male)"],"muscle":"glutes","equipment":"bodyweight","aliases":["hands clasped circular toe touch (male)"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart and your hands clasped together in front of your chest.\nBend your knees slightly and hinge forward at the hips, keeping your back straight.\nLower your hands towards your toes in a circular motion, reaching as far as you can without straining.\nPause for a moment at the bottom, then slowly return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0634\u0628\u0643 \u064a\u062f\u064a\u0643 \u0645\u0639\u064b\u0627 \u0623\u0645\u0627\u0645 \u0635\u062f\u0631\u0643.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u064b\u0627 \u0648\u062b\u0628\u062a\u0647\u0645\u0627 \u0644\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643.\n\u0627\u062e\u0641\u0636 \u064a\u062f\u064a\u0643 \u0646\u062d\u0648 \u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u062d\u0631\u0643\u0629 \u062f\u0627\u0626\u0631\u064a\u0629\u060c \u0644\u062a\u0635\u0644 \u0625\u0644\u0649 \u0623\u0628\u0639\u062f \u0645\u0627 \u062a\u0633\u062a\u0637\u064a\u0639 \u062f\u0648\u0646 \u0625\u062c\u0647\u0627\u062f.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3218","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","quadriceps","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3218-B5xca8s.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3218-B5xca8s.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"2519a112-612f-5a2c-8dae-4613c62a8b92","source_id":"3215","name_en":"hands reversed clasped circular toe touch (male)","name_ar":"\u064a\u062f \u0645\u0639\u0643\u0648\u0633\u0629 \u0645\u062b\u0628\u062a\u0629 \u0628\u0625\u0635\u0628\u0639 \u062f\u0627\u0626\u0631\u064a \u062a\u0639\u0645\u0644 \u0628\u0627\u0644\u0644\u0645\u0633 (\u0630\u0643\u0631)","match_names":["hands reversed clasped circular toe touch (male)"],"muscle":"glutes","equipment":"bodyweight","aliases":["hands reversed clasped circular toe touch (male)"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart and your arms extended to the sides.\nBend forward at the waist, keeping your back straight and your knees slightly bent.\nReach down with your hands and clasp them together behind your legs.\nSlowly raise your hands up and over your head in a circular motion, keeping your legs straight.\nContinue the circular motion until your hands touch your toes.\nReverse the motion and bring your hands back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646.\n\u0627\u0646\u062d\u0646\u0650 \u0644\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u062e\u0635\u0631\u060c \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0642\u0645 \u0628\u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u064a\u062f\u064a\u0643 \u0648\u0634\u0628\u0643\u0647\u0645\u0627 \u0645\u0639\u064b\u0627 \u062e\u0644\u0641 \u0633\u0627\u0642\u064a\u0643.\n\u0627\u0631\u0641\u0639\u064a \u064a\u062f\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0623\u0639\u0644\u0649 \u0648\u0641\u0648\u0642 \u0631\u0623\u0633\u0643 \u0628\u062d\u0631\u0643\u0629 \u062f\u0627\u0626\u0631\u064a\u0629\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0633\u0627\u0642\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062d\u0631\u0643\u0629 \u0627\u0644\u062f\u0627\u0626\u0631\u064a\u0629 \u062d\u062a\u0649 \u062a\u0644\u0645\u0633 \u064a\u062f\u064a\u0643 \u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643.\n\u0627\u0639\u0643\u0633\u064a \u0627\u0644\u062d\u0631\u0643\u0629 \u0648\u0623\u0631\u062c\u0639\u064a \u064a\u062f\u064a\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3215","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","quadriceps","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3215-yq3GAJX.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3215-yq3GAJX.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"48e1119e-331e-572c-82cf-d4c793d53c63","source_id":"3302","name_en":"handstand","name_ar":"\u0627\u0644\u0648\u0642\u0648\u0641 \u0639\u0644\u0649 \u0627\u0644\u064a\u062f\u064a\u0646","match_names":["handstand"],"muscle":"triceps","equipment":"bodyweight","aliases":["handstand"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Find an open space with enough room to perform a handstand.\nPlace your hands on the ground shoulder-width apart, fingers pointing forward.\nKick your legs up towards the wall, using your core and shoulders to maintain balance.\nOnce in a handstand position, engage your triceps to support your body weight.\nHold the handstand for as long as you can maintain balance.\nTo come down, slowly lower your legs back to the ground.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062d\u062b \u0639\u0646 \u0645\u0633\u0627\u062d\u0629 \u0645\u0641\u062a\u0648\u062d\u0629 \u0628\u0647\u0627 \u0645\u0633\u0627\u062d\u0629 \u0643\u0627\u0641\u064a\u0629 \u0644\u0623\u062f\u0627\u0621 \u0627\u0644\u0648\u0642\u0648\u0641 \u0639\u0644\u0649 \u0627\u0644\u064a\u062f\u064a\u0646.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0623\u0635\u0627\u0628\u0639 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645.\n\u0627\u0631\u0641\u0639 \u0633\u0627\u0642\u064a\u0643 \u0646\u062d\u0648 \u0627\u0644\u062d\u0627\u0626\u0637\u060c \u0645\u0633\u062a\u062e\u062f\u0645\u064b\u0627 \u062c\u0630\u0639\u0643 \u0648\u0643\u062a\u0641\u064a\u0643 \u0644\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\u062a\u0648\u0627\u0632\u0646.\n\u0628\u0645\u062c\u0631\u062f \u0623\u0646 \u062a\u0643\u0648\u0646 \u0641\u064a \u0648\u0636\u0639 \u0627\u0644\u0648\u0642\u0648\u0641 \u0639\u0644\u0649 \u0627\u0644\u064a\u062f\u064a\u0646\u060c \u0642\u0645 \u0628\u062a\u0634\u063a\u064a\u0644 \u0627\u0644\u0639\u0636\u0644\u0629 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633 \u0644\u062f\u0639\u0645 \u0648\u0632\u0646 \u062c\u0633\u0645\u0643.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0648\u0642\u0648\u0641 \u0639\u0644\u0649 \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0623\u0637\u0648\u0644 \u0641\u062a\u0631\u0629 \u0645\u0645\u0643\u0646\u0629 \u0644\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\u062a\u0648\u0627\u0632\u0646.\n\u0644\u0644\u0646\u0632\u0648\u0644\u060c \u0642\u0645 \u0628\u062e\u0641\u0636 \u0633\u0627\u0642\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3302","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["shoulders","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3302-XooAdhl.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3302-XooAdhl.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"ccef5f59-0fd3-52db-8568-e610739d173b","source_id":"0471","name_en":"handstand push-up","name_ar":"\u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u064a\u062f\u064a\u0646","match_names":["handstand push-up"],"muscle":"triceps","equipment":"bodyweight","aliases":["handstand push-up"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Find a wall and face away from it, standing a few feet away.\nPlace your hands on the ground shoulder-width apart and kick your feet up against the wall, coming into a handstand position.\nBend your elbows and lower your head towards the ground, keeping your body in a straight line.\nPush through your hands and extend your arms to return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062d\u062b \u0639\u0646 \u062c\u062f\u0627\u0631 \u0648\u0648\u062c\u0647\u0643 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646\u0647\u060c \u0648\u0627\u0642\u0641\u064b\u0627 \u0639\u0644\u0649 \u0628\u0639\u062f \u0628\u0636\u0639\u0629 \u0623\u0642\u062f\u0627\u0645.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u062b\u0645 \u0627\u0631\u0643\u0644 \u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0626\u0637\u060c \u062d\u062a\u0649 \u062a\u062a\u062e\u0630 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0648\u0642\u0648\u0641 \u0639\u0644\u0649 \u0627\u0644\u064a\u062f\u064a\u0646.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0648\u062e\u0641\u0636 \u0631\u0623\u0633\u0643 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u062c\u0633\u0645\u0643 \u0641\u064a \u062e\u0637 \u0645\u0633\u062a\u0642\u064a\u0645.\n\u0627\u062f\u0641\u0639 \u0628\u064a\u062f\u064a\u0643 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0471","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["shoulders","chest","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0471-rQxwMxO.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0471-rQxwMxO.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"f98be86e-8dd2-531c-871b-2876a121db89","source_id":"1764","name_en":"hanging leg hip raise","name_ar":"\u0631\u0641\u0639 \u0627\u0644\u0648\u0631\u0643 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0645\u0639\u0644\u0642\u0629","match_names":["hanging leg hip raise"],"muscle":"core","equipment":"bodyweight","aliases":["hanging leg hip raise"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Hang from a pull-up bar with your arms fully extended and your palms facing away from you.\nEngage your core and lift your legs up by flexing your hips and knees until your thighs are parallel to the ground.\nPause for a moment at the top, then slowly lower your legs back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u0627\u0644\u062a\u0639\u0644\u064a\u0642 \u0645\u0646 \u0634\u0631\u064a\u0637 \u0627\u0644\u0633\u062d\u0628 \u0645\u0639 \u062a\u0645\u062f