43\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0474","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0474-pj0X0tF.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0474-pj0X0tF.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"8e8c16cd-9c14-5d25-8d95-775d2e067a57","source_id":"0475","name_en":"hanging straight leg raise","name_ar":"\u0645\u0639\u0644\u0642\u0629 \u0631\u0641\u0639 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645\u0629","match_names":["hanging straight leg raise"],"muscle":"core","equipment":"bodyweight","aliases":["hanging straight leg raise"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Hang from a pull-up bar with your arms fully extended and your palms facing away from you.\nEngage your core and lift your legs up in front of you, keeping them straight.\nContinue lifting until your legs are parallel to the ground or as high as you can comfortably go.\nPause for a moment at the top, then slowly lower your legs back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u0627\u0644\u062a\u0639\u0644\u064a\u0642 \u0645\u0646 \u0634\u0631\u064a\u0637 \u0627\u0644\u0633\u062d\u0628 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646\u0643.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u0631\u0641\u0639 \u0633\u0627\u0642\u064a\u0643 \u0623\u0645\u0627\u0645\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0626\u0647\u0645\u0627 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0631\u0641\u0639 \u062d\u062a\u0649 \u062a\u0635\u0628\u062d \u0633\u0627\u0642\u064a\u0643 \u0645\u0648\u0627\u0632\u064a\u0629 \u0644\u0644\u0623\u0631\u0636 \u0623\u0648 \u0625\u0644\u0649 \u0623\u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u064a\u0645\u0643\u0646\u0643 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064a\u0647 \u0628\u0634\u0643\u0644 \u0645\u0631\u064a\u062d.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0633\u0627\u0642\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0475","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0475-4Ml7QFO.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0475-4Ml7QFO.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"d6c5fe40-8ef2-5d0d-81c6-bb271c692e93","source_id":"0476","name_en":"hanging straight twisting leg hip raise","name_ar":"\u0645\u0639\u0644\u0642\u0629 \u0639\u0644\u0649 \u0627\u0644\u062a\u0648\u0627\u0644\u064a \u0627\u0644\u062a\u0648\u0627\u0621 \u0627\u0644\u0633\u0627\u0642 \u0631\u0641\u0639 \u0627\u0644\u0648\u0631\u0643","match_names":["hanging straight twisting leg hip raise"],"muscle":"core","equipment":"bodyweight","aliases":["hanging straight twisting leg hip raise"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Hang from a pull-up bar with your arms fully extended and your legs straight.\nEngage your core and lift your legs up towards your chest, keeping them straight.\nOnce your legs are parallel to the ground, twist your hips to one side, bringing your legs towards that side.\nPause for a moment, then return to the starting position.\nRepeat the movement, but this time twist your hips to the opposite side.\nContinue alternating sides for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u0627\u0644\u062a\u0639\u0644\u064a\u0642 \u0645\u0646 \u0634\u0631\u064a\u0637 \u0627\u0644\u0633\u062d\u0628 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u0633\u0627\u0642\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u0629.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u0631\u0641\u0639 \u0633\u0627\u0642\u064a\u0643 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0626\u0647\u0645\u0627 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646.\n\u0628\u0645\u062c\u0631\u062f \u0623\u0646 \u062a\u0635\u0628\u062d \u0633\u0627\u0642\u064a\u0643 \u0645\u0648\u0627\u0632\u064a\u0629 \u0644\u0644\u0623\u0631\u0636\u060c \u0642\u0645 \u0628\u062a\u062d\u0631\u064a\u0641 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0625\u0644\u0649 \u062c\u0627\u0646\u0628 \u0648\u0627\u062d\u062f\u060c \u0648\u062c\u0644\u0628 \u0633\u0627\u0642\u064a\u0643 \u0646\u062d\u0648 \u0647\u0630\u0627 \u0627\u0644\u062c\u0627\u0646\u0628.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0639\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u0648\u0644\u0643\u0646 \u0647\u0630\u0647 \u0627\u0644\u0645\u0631\u0629 \u0642\u0645 \u0628\u0644\u0641 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0476","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["obliques","hip flexors"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0476-Q6bvyen.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0476-Q6bvyen.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"2dbfa28b-63f8-5632-8bf1-1047bb987d42","source_id":"3636","name_en":"high knee against wall","name_ar":"\u0627\u0644\u0631\u0643\u0628\u0629 \u0627\u0644\u0639\u0627\u0644\u064a\u0629 \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0626\u0637","match_names":["high knee against wall"],"muscle":"cardio","equipment":"bodyweight","aliases":["high knee against wall"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Stand facing a wall with your feet hip-width apart.\nPlace your hands on the wall for support.\nEngage your core and lift your right knee up towards your chest, while keeping your left foot on the ground.\nQuickly switch legs, bringing your left knee up towards your chest and lowering your right foot back down.\nContinue alternating legs in a running motion, bringing your knees up as high as possible.\nMaintain a fast pace and keep your upper body stable throughout the exercise.\nRepeat for the desired duration or number of repetitions.","steps_ar":"\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u062d\u0627\u0626\u0637 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0648\u0631\u0643.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0626\u0637 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u062f\u0639\u0645.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u0631\u0641\u0639 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0642\u0645 \u0628\u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646 \u0628\u0633\u0631\u0639\u0629\u060c \u0645\u0639 \u0631\u0641\u0639 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643 \u0648\u062e\u0641\u0636 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0625\u0644\u0649 \u0623\u0633\u0641\u0644.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646 \u0641\u064a \u062d\u0631\u0643\u0629 \u0627\u0644\u062c\u0631\u064a\u060c \u0645\u0639 \u0631\u0641\u0639 \u0631\u0643\u0628\u062a\u064a\u0643 \u0625\u0644\u0649 \u0623\u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0645\u0645\u0643\u0646.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0648\u062a\u064a\u0631\u0629 \u0633\u0631\u064a\u0639\u0629 \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u062b\u0628\u0627\u062a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0637\u0648\u0627\u0644 \u0627\u0644\u062a\u0645\u0631\u064a\u0646.\n\u0643\u0631\u0631 \u0644\u0644\u0645\u062f\u0629 \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629 \u0623\u0648 \u0639\u062f\u062f \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3636","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"cardio","classification_status":"needs_review","source_target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3636-ealLwvX.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3636-ealLwvX.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"6a4ff9be-dcf6-5443-82f9-138d31701c1e","source_id":"0484","name_en":"hip raise (bent knee)","name_ar":"\u0631\u0641\u0639 \u0627\u0644\u0648\u0631\u0643 (\u062b\u0646\u064a \u0627\u0644\u0631\u0643\u0628\u0629)","match_names":["hip raise (bent knee)"],"muscle":"core","equipment":"bodyweight","aliases":["hip raise (bent knee)"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Lie flat on your back with your knees bent and feet flat on the ground.\nPlace your hands by your sides, palms facing down.\nEngage your core and glutes, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.\nPause for a moment at the top, then slowly lower your hips back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a\u0643\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0633\u0641\u0644.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0627\u0644\u062c\u0630\u0639 \u0648\u0627\u0644\u0623\u0631\u062f\u0627\u0641\u060c \u062b\u0645 \u0627\u0631\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636 \u062d\u062a\u0649 \u064a\u0634\u0643\u0644 \u062c\u0633\u0645\u0643 \u062e\u0637\u064b\u0627 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627 \u0645\u0646 \u0631\u0643\u0628\u062a\u064a\u0643 \u0625\u0644\u0649 \u0643\u062a\u0641\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0648\u0631\u0643\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0484","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["glutes","hamstrings"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0484-196HJGw.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0484-196HJGw.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"c5d97e67-d0bc-5a25-83ea-cb86a6c1c2c3","source_id":"1418","name_en":"hug keens to chest","name_ar":"\u0639\u0646\u0627\u0642 \u064a\u062d\u0631\u0635 \u0639\u0644\u0649 \u0627\u0644\u0635\u062f\u0631","match_names":["hug keens to chest"],"muscle":"glutes","equipment":"bodyweight","aliases":["hug keens to chest"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start by standing with your feet shoulder-width apart.\nBend your knees and lower your body down into a squat position.\nAs you squat down, bring your knees up towards your chest and hug them with your arms.\nHold this position for a moment, then slowly return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u0648\u0642\u0648\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621.\n\u0623\u062b\u0646\u0627\u0621 \u062c\u0644\u0648\u0633\u0643 \u0641\u064a \u0648\u0636\u0639 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621\u060c \u0627\u0631\u0641\u0639 \u0631\u0643\u0628\u062a\u064a\u0643 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643 \u0648\u0627\u062d\u062a\u0636\u0646\u0647\u0645\u0627 \u0628\u0630\u0631\u0627\u0639\u064a\u0643.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0648\u0636\u0639 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1418","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","quadriceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1418-znP9SIh.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1418-znP9SIh.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"130e27fc-acc5-56a0-8864-f65f745f41ba","source_id":"3234","name_en":"hyght dumbbell fly","name_ar":"\u0647\u0627\u064a\u062a \u0627\u0644\u062f\u0645\u0628\u0644 \u064a\u0637\u064a\u0631","match_names":["hyght dumbbell fly"],"muscle":"chest","equipment":"dumbbell","aliases":["hyght dumbbell fly"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Lie flat on a bench with a dumbbell in each hand, palms facing each other.\nExtend your arms straight up over your chest, with a slight bend in your elbows.\nKeeping a slight bend in your elbows, lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.\nPause for a moment, then reverse the movement and bring the dumbbells back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u0650 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0639 \u0648\u062c\u0648\u062f \u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u0645\u0639 \u0648\u0636\u0639 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636.\n\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0641\u0648\u0642 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0646\u062d\u0646\u0627\u0621 \u0628\u0633\u064a\u0637 \u0641\u064a \u0645\u0631\u0641\u0642\u064a\u0643\u060c \u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0641\u064a \u0642\u0648\u0633 \u0639\u0631\u064a\u0636 \u062d\u062a\u0649 \u062a\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0635\u062f\u0631\u0643.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u0639\u0643\u0633 \u0627\u0644\u062d\u0631\u0643\u0629 \u0648\u0623\u0639\u062f \u0627\u0644\u062f\u0645\u0628\u0644 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3234","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3234-P9ZRyLT.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3234-P9ZRyLT.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"c80e21c2-784f-58b4-8db8-03905e6c8c9e","source_id":"0489","name_en":"hyperextension","name_ar":"\u0641\u0631\u0637 \u0627\u0644\u062a\u0645\u062f\u062f","match_names":["hyperextension"],"muscle":"back","equipment":"bodyweight","aliases":["hyperextension"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Adjust the hyperextension bench so that your upper thighs are resting on the pad and your feet are secured.\nCross your arms over your chest or place your hands behind your head.\nLower your upper body towards the ground while keeping your back straight.\nPause for a moment at the bottom, then raise your upper body back up until it is in line with your legs.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0645\u0642\u0639\u062f \u0641\u0631\u0637 \u0627\u0644\u062a\u0645\u062f\u062f \u0628\u062d\u064a\u062b \u064a\u0633\u062a\u0642\u0631 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0641\u062e\u0630\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0648\u0633\u0627\u062f\u0629 \u0648\u064a\u062a\u0645 \u062a\u0623\u0645\u064a\u0646 \u0642\u062f\u0645\u064a\u0643.\n\u0627\u0639\u0628\u0631 \u0630\u0631\u0627\u0639\u064a\u0643 \u0639\u0644\u0649 \u0635\u062f\u0631\u0643 \u0623\u0648 \u0636\u0639 \u064a\u062f\u064a\u0643 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643.\n\u0627\u062e\u0641\u0636 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0627\u0631\u0641\u0639 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u062d\u062a\u0649 \u064a\u062a\u0645\u0627\u0634\u0649 \u0645\u0639 \u0633\u0627\u0642\u064a\u0643.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0489","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"spine","secondary_muscles":["glutes","hamstrings"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0489-zhMwOwE.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0489-zhMwOwE.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"f11719e1-794b-5389-8577-e1811010cfe5","source_id":"0488","name_en":"hyperextension (on bench)","name_ar":"\u0641\u0631\u0637 \u0627\u0644\u062a\u0645\u062f\u062f (\u0639\u0644\u0649 \u0645\u0642\u0627\u0639\u062f \u0627\u0644\u0628\u062f\u0644\u0627\u0621)","match_names":["hyperextension (on bench)"],"muscle":"back","equipment":"bodyweight","aliases":["hyperextension (on bench)"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Adjust the hyperextension bench so that your hips are resting comfortably on the pad and your feet are secured.\nCross your arms over your chest or place your hands behind your head.\nSlowly lower your upper body towards the ground while keeping your back straight.\nPause for a moment at the bottom, then raise your upper body back up until it is in line with your legs.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0645\u0642\u0639\u062f \u0641\u0631\u0637 \u0627\u0644\u062a\u0645\u062f\u062f \u0628\u062d\u064a\u062b \u064a\u0633\u062a\u0642\u0631 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0628\u0634\u0643\u0644 \u0645\u0631\u064a\u062d \u0639\u0644\u0649 \u0627\u0644\u0648\u0633\u0627\u062f\u0629 \u0648\u064a\u062a\u0645 \u062a\u0623\u0645\u064a\u0646 \u0642\u062f\u0645\u064a\u0643.\n\u0627\u0639\u0628\u0631 \u0630\u0631\u0627\u0639\u064a\u0643 \u0639\u0644\u0649 \u0635\u062f\u0631\u0643 \u0623\u0648 \u0636\u0639 \u064a\u062f\u064a\u0643 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0627\u0631\u0641\u0639 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u062d\u062a\u0649 \u064a\u062a\u0645\u0627\u0634\u0649 \u0645\u0639 \u0633\u0627\u0642\u064a\u0643.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0488","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"spine","secondary_muscles":["glutes","hamstrings"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0488-zkgRrbK.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0488-zkgRrbK.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"fae925d7-fc57-533b-8105-3f75aadf68dc","source_id":"3289","name_en":"impossible dips","name_ar":"\u0627\u0644\u0627\u0646\u062e\u0641\u0627\u0636\u0627\u062a \u0627\u0644\u0645\u0633\u062a\u062d\u064a\u0644\u0629","match_names":["impossible dips"],"muscle":"triceps","equipment":"bodyweight","aliases":["impossible dips"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Position yourself between two parallel bars with your arms fully extended and your body suspended in the air.\nBend your knees and cross your ankles.\nLower your body by bending your elbows until your upper arms are parallel to the ground.\nPause for a moment, then push yourself back up to the starting position by straightening your arms.\nRepeat for the desired number of repetitions.","steps_ar":"\u0636\u0639 \u0646\u0641\u0633\u0643 \u0628\u064a\u0646 \u0642\u0636\u064a\u0628\u064a\u0646 \u0645\u062a\u0648\u0627\u0632\u064a\u064a\u0646 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0645\u062f\u0648\u062f\u062a\u064a\u0646 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u062c\u0633\u0645\u0643 \u0645\u0639\u0644\u0642 \u0641\u064a \u0627\u0644\u0647\u0648\u0627\u0621.\n\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0639\u0628\u0631 \u0643\u0627\u062d\u0644\u064a\u0643.\n\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0648\u0627\u0632\u064a\u064b\u0627 \u0644\u0644\u0623\u0631\u0636.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0646\u0641\u0633\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0641\u0631\u062f \u0630\u0631\u0627\u0639\u064a\u0643.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3289","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["chest","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3289-05Cf2v8.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3289-05Cf2v8.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"3461a825-8781-5b4c-886d-d5e1103af314","source_id":"1471","name_en":"inchworm","name_ar":"\u062f\u0648\u062f\u0629 \u0628\u0648\u0635\u0629","match_names":["inchworm"],"muscle":"core","equipment":"bodyweight","aliases":["inchworm"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start in a standing position with your feet hip-width apart.\nBend forward at the waist and place your hands on the ground in front of you.\nWalk your hands forward until you are in a high plank position, with your body in a straight line from head to toe.\nPause for a moment, then walk your hands back towards your feet, keeping your legs as straight as possible.\nOnce your hands reach your feet, stand back up to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0648\u0642\u0648\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0645\u0641\u0635\u0644 \u0627\u0644\u0648\u0631\u0643.\n\u0627\u0646\u062d\u0646\u0649 \u0644\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u062e\u0635\u0631 \u0648\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0623\u0645\u0627\u0645\u0643.\n\u0627\u0645\u0634\u0650 \u0628\u064a\u062f\u064a\u0643 \u0644\u0644\u0623\u0645\u0627\u0645 \u062d\u062a\u0649 \u062a\u0635\u0644 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0644\u0648\u062d \u0627\u0644\u062e\u0634\u0628\u064a \u0627\u0644\u0645\u0631\u062a\u0641\u0639\u060c \u0645\u0639 \u062c\u0639\u0644 \u062c\u0633\u0645\u0643 \u0641\u064a \u062e\u0637 \u0645\u0633\u062a\u0642\u064a\u0645 \u0645\u0646 \u0627\u0644\u0631\u0623\u0633 \u0625\u0644\u0649 \u0623\u062e\u0645\u0635 \u0627\u0644\u0642\u062f\u0645\u064a\u0646.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u0631\u062c\u0639 \u064a\u062f\u064a\u0643 \u0646\u062d\u0648 \u0642\u062f\u0645\u064a\u0643\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0633\u0627\u0642\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646 \u0642\u062f\u0631 \u0627\u0644\u0625\u0645\u0643\u0627\u0646.\n\u0628\u0645\u062c\u0631\u062f \u0623\u0646 \u062a\u0635\u0644 \u064a\u062f\u064a\u0643 \u0625\u0644\u0649 \u0642\u062f\u0645\u064a\u0643\u060c \u